    # 筛选与输出：任一失败则整次命令报错，不输出部分结果。
    statuses = [check_file_status(record["path"]) for record in result]
    if args.file_status is not None:
        # --file-status 只改变入选范围：按当前状态过滤候选，
        # 保持首次登记顺序，每条素材仍只出现一次。
